def chain_follow(chain):
    chain_list = list(chain)
    chain_list.sort()
    result = []
    for i in range(len(chain_list)):
        if i == 0:
            result.append(chain_list[i])
        else:
            if chain_list[i-1][0] == chain_list[i][0]:
                result.append(chain_list[i][1])
            else:
                result.append(chain_list[i][1])
                result.append(chain_list[i-1][1])
    return ','.join(result)
